 function initHomeMotion(){
  if(standalone){window.SMOKERS_MOUNT_ORBIT?.(root);window.SMOKERS_MOUNT_PRO?.(root,motionEnabled());window.SMOKERS_MOUNT_GALLERY?.(root)}
  else{loadFeature('orbit-menu','.ss-orbit-mount');loadFeature('pro-showcase','.ss-pro-showcase-mount');loadFeature('gallery-carousel','.ss-gallery-mount')}
  homeMotionCleanup?.();homeMotionCleanup=null;fireCleanup?.();fireCleanup=window.SMOKERS_BRAND_FIRE?.(root,motionEnabled());
  if(root.dataset.mode==='method'){
   const sections=[...root.querySelectorAll('.ss-method-page-section')];
   if(!sections.length)return;
   const reset=()=>{sections.forEach(s=>{s.style.removeProperty('--mp-y');delete s.dataset.methodEntered})};
   if(!motionEnabled()){sections.forEach(s=>s.dataset.methodEntered='true');homeMotionCleanup=reset;return}
   let frame=0;
   const paint=()=>{
    frame=0;
    const vh=innerHeight||900;
    for(const s of sections){
     const r=s.getBoundingClientRect();
     if(r.top<=vh*.88&&r.bottom>=0)s.dataset.methodEntered='true';
     const center=(r.top+r.height*.5-vh*.5)/vh;
     const clamped=Math.max(-1,Math.min(1,center));
     s.style.setProperty('--mp-y',clamped.toFixed(4));
    }
   };
   const request=()=>{if(!frame)frame=requestAnimationFrame(paint)};
   addEventListener('scroll',request,{passive:true});addEventListener('resize',request);paint();
   homeMotionCleanup=()=>{removeEventListener('scroll',request);removeEventListener('resize',request);cancelAnimationFrame(frame);reset()};
   return;
  }
  const hero=root.querySelector('.ss-flat-hero'),wrapper=root.querySelector('.ss-home-transition');
  if(!hero||!wrapper){delete root.dataset.heroVisible;return}
  if(hero.classList.contains('ss-kitchen-hero')){
   homeMotionCleanup=window.SMOKERS_B2C_MOTION?.(root,motionEnabled);return;
  }
  const reset=()=>{delete hero.dataset.parallax;hero.style.removeProperty('--hero-scale')};
  reset();if(!motionEnabled())return;
  let frame=0,current=0,target=0,last=0;
  const paint=now=>{
   const dt=last?Math.min(64,now-last):16;last=now;
   current+=(target-current)*(1-Math.exp(-dt/105));
   if(Math.abs(target-current)<.0005)current=target;
   hero.style.setProperty('--hero-scale',String(1-current*.08));
   if(current!==target)frame=requestAnimationFrame(paint);else{frame=0;last=0}
  };
  const measure=()=>{
   const enabled=innerWidth>1100;
   hero.dataset.parallax=String(enabled);
   target=enabled?Math.max(0,Math.min(1,-wrapper.getBoundingClientRect().top/innerHeight)):0;
   if(!frame)frame=requestAnimationFrame(paint);
  };
  addEventListener('scroll',measure,{passive:true});addEventListener('resize',measure);measure();
  homeMotionCleanup=()=>{removeEventListener('scroll',measure);removeEventListener('resize',measure);cancelAnimationFrame(frame);reset()};
 }
